import base64
script = r'''
import re
import shutil
import sys
from collections import defaultdict
from openpyxl import load_workbook

def values(ws):
    for row in ws.rows:
        yield [cell.value for cell in row]

def load_xlsx(path, staged_name):
    shutil.copyfile(path, staged_name)
    return load_workbook(staged_name, read_only=False, data_only=True)

def norm_text(x):
    return str(x).strip() if x is not None else ''

genes_path, variants_path, counts_path, top_path = sys.argv[1:5]

chip_wb = load_xlsx(genes_path, 'chip_genes.xlsx')
chip_ws = chip_wb.worksheets[0]
chip_genes = set()
for row in values(chip_ws):
    if not row:
        continue
    gene = norm_text(row[0])
    if gene:
        chip_genes.add(gene)
if not chip_genes:
    raise SystemExit('No CHIP genes loaded')

var_wb = load_xlsx(variants_path, 'variants.xlsx')
var_ws = var_wb.worksheets[0]
rows = list(values(var_ws))
if len(rows) < 3:
    raise SystemExit('Variant workbook has fewer than three rows')
headers = [norm_text(x) for x in rows[1]]
idx = {h: i for i, h in enumerate(headers)}
for required in ['Zygosity', 'Gene Names']:
    if required not in idx:
        raise SystemExit('Missing required variant column: ' + required)

counts = defaultdict(int)
retained_rows = 0
for row in rows[2:]:
    if not row or all(x is None for x in row):
        continue
    zyg = norm_text(row[idx['Zygosity']]) if idx['Zygosity'] < len(row) else ''
    if not zyg or zyg.lower() == 'reference':
        continue
    gene_text = norm_text(row[idx['Gene Names']]) if idx['Gene Names'] < len(row) else ''
    if not gene_text:
        continue
    row_genes = []
    for token in re.split(r'[,;/\\s]+', gene_text):
        token = token.strip()
        if token and token in chip_genes and token not in row_genes:
            row_genes.append(token)
    if not row_genes:
        continue
    retained_rows += 1
    for gene in row_genes:
        counts[gene] += 1
if not counts:
    raise SystemExit('No non-reference CHIP gene variants counted')
ordered = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))
with open(counts_path, 'w') as out:
    out.write('gene\\tnon_reference_variant_count\\n')
    for gene, count in ordered:
        out.write('%s\\t%d\\n' % (gene, count))
with open(top_path, 'w') as out:
    out.write('gene\\tnon_reference_variant_count\\tretained_variant_rows\\n')
    out.write('%s\\t%d\\t%d\\n' % (ordered[0][0], ordered[0][1], retained_rows))
'''
print(base64.b64encode(script.encode()).decode())
PY"
